-- Schema-only transcription from the active database, 2026-10-21. No live rows.
CREATE TABLE public.commercial_lots (id uuid NOT NULL DEFAULT gen_random_uuid(), project_id uuid NOT NULL, entity_id uuid NOT NULL, public_identifier text NOT NULL, block text, lot_number text, level_label text, display_name text NOT NULL, description text, status text NOT NULL DEFAULT 'AVAILABLE'::text, official_area_sqm numeric(14,4), calculated_area_sqm numeric(14,4), area_validation_status text NOT NULL DEFAULT 'UNVALIDATED'::text, frontage_meters numeric(12,4), depth_meters numeric(12,4), infrastructure jsonb NOT NULL DEFAULT '[]'::jsonb, has_electricity boolean NOT NULL DEFAULT false, has_water boolean NOT NULL DEFAULT false, has_internet boolean NOT NULL DEFAULT false, is_corner boolean NOT NULL DEFAULT false, is_covered boolean NOT NULL DEFAULT false, accessibility_notes text, commercial_notes text, internal_notes text, archived_at timestamp with time zone, superseded_by_lot_id uuid, created_by uuid, updated_by uuid, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.lot_sale_installments (id uuid NOT NULL DEFAULT gen_random_uuid(), order_id uuid NOT NULL, installment_number integer NOT NULL, due_date date NOT NULL, amount numeric(14,2) NOT NULL, payment_status text NOT NULL DEFAULT 'PENDING'::text, paid_at timestamp with time zone, notes text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.lot_sale_order_items (id uuid NOT NULL DEFAULT gen_random_uuid(), order_id uuid NOT NULL, lot_id uuid NOT NULL, public_identifier text NOT NULL, official_area_snapshot numeric(14,2) NOT NULL, price_per_sqm_snapshot numeric(14,2) NOT NULL, pricing_rule_id uuid, pricing_rule_label text, pricing_stage text NOT NULL, item_total numeric(14,2) NOT NULL, original_status text NOT NULL, sale_id uuid, created_at timestamp with time zone NOT NULL DEFAULT now(), contract_state text NOT NULL DEFAULT 'PENDING_SIGNATURE'::text, signed_at timestamp with time zone, signed_by uuid, cancelled_at timestamp with time zone, cancelled_by uuid, PRIMARY KEY (id));
CREATE TABLE public.lot_sale_order_revisions (id uuid NOT NULL DEFAULT gen_random_uuid(), order_id uuid NOT NULL, added_lot_ids uuid[] NOT NULL DEFAULT '{}'::uuid[], removed_lot_ids uuid[] NOT NULL DEFAULT '{}'::uuid[], before_state jsonb NOT NULL, after_state jsonb NOT NULL, reason text NOT NULL, actor_user_id uuid, created_at timestamp with time zone NOT NULL DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.lot_sale_orders (id uuid NOT NULL DEFAULT gen_random_uuid(), project_id uuid NOT NULL, buyer_name text NOT NULL, document_number text, phone text, email text, stage text NOT NULL, official_area_total numeric(14,2) NOT NULL DEFAULT 0, negotiated_total numeric(14,2) NOT NULL DEFAULT 0, payment_type text NOT NULL, installment_count integer NOT NULL DEFAULT 1, payment_method text NOT NULL, first_due_date date, status text NOT NULL DEFAULT 'CONFIRMED'::text, notes text, salesperson_user_id uuid NOT NULL, idempotency_key text NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), reverted_at timestamp with time zone, reverted_by uuid, exhibitor_id uuid, spaces_subtotal numeric, fee_admin numeric NOT NULL DEFAULT 0, fee_ppci numeric NOT NULL DEFAULT 0, fee_cleaning_license numeric NOT NULL DEFAULT 0, fees_total numeric NOT NULL DEFAULT 0, logo_path text, buyer_trade_name text, PRIMARY KEY (id));
CREATE TABLE public.lot_sales (id uuid NOT NULL DEFAULT gen_random_uuid(), lot_id uuid NOT NULL, buyer_name text NOT NULL, document_number text, negotiated_value numeric(14,2) NOT NULL, sale_date date NOT NULL, salesperson_user_id uuid NOT NULL, salesperson_name text NOT NULL, contract_number text, payment_status text NOT NULL DEFAULT 'PENDING'::text, internal_notes text, status text NOT NULL DEFAULT 'CONFIRMED'::text, created_at timestamp with time zone NOT NULL DEFAULT now(), reverted_at timestamp with time zone, reverted_by uuid, buyer_trade_name text, PRIMARY KEY (id));
CREATE TABLE public.lot_status_history (id uuid NOT NULL DEFAULT gen_random_uuid(), lot_id uuid NOT NULL, previous_status text, new_status text NOT NULL, reason text, changed_by uuid NOT NULL, changed_at timestamp with time zone NOT NULL DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.map_activity_logs (id uuid NOT NULL DEFAULT gen_random_uuid(), org_id uuid NOT NULL, project_id uuid NOT NULL, entity_id uuid, lot_id uuid, action text NOT NULL, before_state jsonb, after_state jsonb, reason text, actor_user_id uuid, created_at timestamp with time zone NOT NULL DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.map_projects (id uuid NOT NULL DEFAULT gen_random_uuid(), org_id uuid NOT NULL, name text NOT NULL, description text, coordinate_system text NOT NULL DEFAULT 'LOCAL_NORMALIZED'::text, reference_width numeric(14,6) NOT NULL DEFAULT 120, reference_height numeric(14,6) NOT NULL DEFAULT 67.5, active_version integer NOT NULL DEFAULT 1, is_published boolean NOT NULL DEFAULT false, is_archived boolean NOT NULL DEFAULT false, created_by uuid, updated_by uuid, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), reference_revision text, PRIMARY KEY (id));
ALTER TABLE public.lot_sale_installments ADD CONSTRAINT lot_sale_installments_amount_check CHECK ((amount >= (0)::numeric));
ALTER TABLE public.lot_sale_installments ADD CONSTRAINT lot_sale_installments_installment_number_check CHECK ((installment_number >= 1));
