ALTER TABLE public.lot_sale_order_items ADD CONSTRAINT lot_sale_order_items_contract_state_check CHECK ((contract_state = ANY (ARRAY['PENDING_SIGNATURE'::text, 'SIGNED'::text, 'CANCELLED'::text, 'LEGACY_UNVERIFIED'::text])));
ALTER TABLE public.lot_sale_orders ADD CONSTRAINT lot_sale_orders_fee_admin_check CHECK ((fee_admin >= (0)::numeric));
ALTER TABLE public.lot_sale_orders ADD CONSTRAINT lot_sale_orders_fee_cleaning_license_check CHECK ((fee_cleaning_license >= (0)::numeric));
ALTER TABLE public.lot_sale_orders ADD CONSTRAINT lot_sale_orders_fee_ppci_check CHECK ((fee_ppci >= (0)::numeric));
ALTER TABLE public.lot_sale_orders ADD CONSTRAINT lot_sale_orders_fees_total_check CHECK ((fees_total >= (0)::numeric));
ALTER TABLE public.lot_sale_orders ADD CONSTRAINT lot_sale_orders_installment_count_check CHECK ((installment_count >= 1));
ALTER TABLE public.lot_sale_orders ADD CONSTRAINT lot_sale_orders_payment_type_check CHECK ((payment_type = ANY (ARRAY['CASH'::text, 'INSTALLMENTS'::text])));
ALTER TABLE public.lot_sale_orders ADD CONSTRAINT lot_sale_orders_stage_check CHECK ((stage = ANY (ARRAY['RENOVACAO'::text, 'SEGUNDA_ETAPA'::text])));
